fn enc_request_identity(out: &mut Vec<u8>, v: &RequestIdentity, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "key");
    out.extend_from_slice(b": ");
    esc(out, &v.key);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "history_epoch");
    out.extend_from_slice(b": ");
    esc(out, &v.history_epoch);
    if v.attempt != 0 {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "attempt");
        out.extend_from_slice(b": ");
        num(out, v.attempt);
    }
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

fn enc_submission(out: &mut Vec<u8>, v: &Submission, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "identity");
    out.extend_from_slice(b": ");
    enc_request_identity(out, &v.identity, depth + 1);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "kind");
    out.extend_from_slice(b": ");
    esc(out, &v.kind);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "spec");
    out.extend_from_slice(b": ");
    esc(out, &encode_binary(&v.spec));
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "required_guarantees");
    out.extend_from_slice(b": ");
    strs(out, &v.required_guarantees, depth + 1);
    if !v.label.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "label");
        out.extend_from_slice(b": ");
        esc(out, &v.label);
    }
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

fn enc_receipt(out: &mut Vec<u8>, v: &Receipt, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "identity");
    out.extend_from_slice(b": ");
    enc_request_identity(out, &v.identity, depth + 1);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "logical_owner");
    out.extend_from_slice(b": ");
    esc(out, &v.logical_owner);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "operation_id");
    out.extend_from_slice(b": ");
    esc(out, &v.operation_id);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "accepted_guarantees");
    out.extend_from_slice(b": ");
    strs(out, &v.accepted_guarantees, depth + 1);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "history_retention_ms");
    out.extend_from_slice(b": ");
    num(out, v.history_retention_ms);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

fn enc_acceptance_result(out: &mut Vec<u8>, v: &AcceptanceResult, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "outcome");
    out.extend_from_slice(b": ");
    esc(out, v.outcome.as_str());
    if let Some(value) = &v.receipt {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "receipt");
        out.extend_from_slice(b": ");
        enc_receipt(out, value, depth + 1);
    }
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "reason");
    out.extend_from_slice(b": ");
    esc(out, &v.reason);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

